package com.gittexplorer.documentextractor.service;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
import com.gittexplorer.documentextractor.extractor.TextExtractionService;import com.gittexplorer.documentextractor.service.impl.DocumentServiceImpl;import com.gittexplorer.documentextractor.util.FileNameUtility;import com.gittexplorer.documentextractor.util.HashUtility;import com.gittexplorer.documentextractor.validation.FileValidationService;import java.util.List;import java.util.Map;import java.util.concurrent.Executors;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockMultipartFile;
class DocumentServiceImplTest { @Test void processesMultipleFiles(){FileValidationService validation=mock(FileValidationService.class);TextExtractionService extractor=mock(TextExtractionService.class);RegexExtractionService regex=mock(RegexExtractionService.class);when(extractor.detectMimeType(any(),any())).thenReturn("text/plain");when(extractor.extract(any(),any())).thenReturn("CUST12345678");when(regex.extractIdentifiers(any())).thenReturn(Map.of("CUSTOMER_ID",List.of("CUST12345678")));var svc=new DocumentServiceImpl(validation,extractor,regex,new HashUtility(),new FileNameUtility(),Executors.newFixedThreadPool(2));var response=svc.extract(new MockMultipartFile[]{new MockMultipartFile("files","a.txt","text/plain","hello".getBytes()),new MockMultipartFile("files","b.txt","text/plain","world".getBytes())});assertThat(response.summary().documentsSucceeded()).isEqualTo(2);assertThat(response.documents()).hasSize(2);} @Test void marksSingleExtractionFailure(){FileValidationService validation=mock(FileValidationService.class);TextExtractionService extractor=mock(TextExtractionService.class);RegexExtractionService regex=mock(RegexExtractionService.class);when(extractor.detectMimeType(any(),any())).thenReturn("text/plain");when(extractor.extract(any(),eq("bad.txt"))).thenThrow(new com.gittexplorer.documentextractor.exception.DocumentExtractionException("Unable to extract text"));when(extractor.extract(any(),eq("good.txt"))).thenReturn("ok");var svc=new DocumentServiceImpl(validation,extractor,regex,new HashUtility(),new FileNameUtility(),Runnable::run);var response=svc.extract(new MockMultipartFile[]{new MockMultipartFile("files","bad.txt","text/plain","bad".getBytes()),new MockMultipartFile("files","good.txt","text/plain","ok".getBytes())});assertThat(response.summary().documentsFailed()).isEqualTo(1);} }
